package com.bank.dsa;

import java.math.BigDecimal;
import java.util.logging.*;

// Runnable demo: pick the highest of three rate offers.
public class LargerOfThreeDemo {
    private static final Logger log = Logger.getLogger(LargerOfThreeDemo.class.getName());

    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        Logger root = Logger.getLogger("");
        for (Handler old : root.getHandlers()) root.removeHandler(old);
        root.addHandler(h);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        BestOfferSelector selector = new BestOfferSelector();

        BigDecimal offerA = new BigDecimal("5.00");   // A
        BigDecimal offerB = new BigDecimal("18.00");  // B
        BigDecimal offerC = new BigDecimal("11.00");  // C
        BigDecimal best = selector.largest(offerA, offerB, offerC);
        log.info(() -> "Rajesh FD best offer selected = " + best + "%");
    }
}

// ─── Would be in BestOfferSelector.java in a real project ───
class BestOfferSelector {
    // Nested comparison using >= so ties still select a value. compareTo compares numeric value.
    BigDecimal largest(BigDecimal a, BigDecimal b, BigDecimal c) {
        if (a == null || b == null || c == null) {
            throw new IllegalArgumentException("Offers must not be null");
        }
        if (a.compareTo(b) >= 0 && a.compareTo(c) >= 0) {  // A >= B AND A >= C ?
            return a;
        } else if (b.compareTo(c) >= 0) {                  // else B >= C ?
            return b;
        } else {
            return c;
        }
    }
}

// ─── Would be in BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
